import itertools, sys

vars = ['a','b','c','d']
# map variable name to index
var_idx = {v:i for i,v in enumerate(vars)}

def eval_lit(lit, assign):
    # lit is (var, sign) sign True for positive, False for negated
    v, pos = lit
    val = assign[var_idx[v]]
    return val if pos else not val

def clause_satisfied(clause, assign):
    vals = [eval_lit(l, assign) for l in clause]
    # NAE satisfied if not all equal
    return not (all(vals) or not any(vals))

def gadget_ok(clauses):
    # For each assign to a,b,c (d free), condition
    for a,b,c in itertools.product([False,True], repeat=3):
        orig_sat = (a or b or c)
        # we need existence of d assignment making all clauses NAE satisfied iff orig_sat
        possible=False
        for d in [False,True]:
            assign = [a,b,c,d]
            if all(clause_satisfied(cl, assign) for cl in clauses):
                possible=True
                break
        if possible != orig_sat:
            return False
    return True

# generate all possible literals over vars
literals = []
for v in vars:
    literals.append((v, True))
    literals.append((v, False))

# generate all possible clauses (distinct vars)
all_clauses = []
for combo in itertools.combinations(vars,3):
    for signs in itertools.product([True, False], repeat=3):
        clause = [(v, s) for v,s in zip(combo, signs)]
        all_clauses.append(clause)

# search for small sets of clauses up to size 2 using d as aux
for size in range(1,3):
    for combo in itertools.combinations(all_clauses, size):
        # ensure each clause contains at most one occurrence of each var (already) but may include only a,b,c,d.
        # also ensure at least one clause includes d? not required.
        if gadget_ok(combo):
            print('found', size, combo)
            sys.exit()
print('none found')
