import random
import itertools
import json
import sys
from pathlib import Path

# import problem definitions for validation (optional)
import problems
from reduce import reduce

def solve_3sat(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for assign in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            vals = [(assign[abs(l)-1] if l>0 else not assign[abs(l)-1]) for l in clause]
            if not any(vals):
                ok = False
                break
        if ok:
            return True
    return False

def solve_naesat(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for assign in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            vals = [(assign[abs(l)-1] if l>0 else not assign[abs(l)-1]) for l in clause]
            # NAE condition: not all true and not all false
            if all(vals) or not any(vals):
                ok = False
                break
        if ok:
            return True
    return False

def random_instance(num_vars, num_clauses):
    clauses = []
    vars_range = list(range(1, num_vars+1))
    for _ in range(num_clauses):
        # pick 3 distinct vars
        vars_selected = random.sample(vars_range, 3)
        clause = []
        for v in vars_selected:
            sign = random.choice([1, -1])
            clause.append(sign * v)
        clauses.append(clause)
    return {"num_vars": num_vars, "clauses": clauses}

random.seed(0)
tests = []
passed = 0
failed = 0
# generate various sizes
for m in range(0,5):
    for num_clauses in range(0,5):
        for _ in range(30):
            inst = random_instance(m, num_clauses)
            # validate using problem classes (may raise)
            try:
                problems.ThreeSat.validate(inst)
            except Exception as e:
                # if invalid (e.g., m<3 with clauses), skip
                continue
            reduced = reduce(inst)
            # validate reduced instance
            problems.NaeThreeSat.validate(reduced)
            ans1 = solve_3sat(inst)
            ans2 = solve_naesat(reduced)
            ok = (ans1 == ans2)
            if ok:
                passed += 1
            else:
                failed += 1
                tests.append({"instance": inst, "reduced": reduced, "ans1": ans1, "ans2": ans2})

verdict = {
    "verified": failed == 0,
    "tests_run": passed + failed,
    "tests_passed": passed,
}
print(json.dumps(verdict, indent=2))
if failed:
    print("Failed cases:", file=sys.stderr)
    for t in tests[:5]:
        print(t, file=sys.stderr)
    sys.exit(1)
EOF"}

