import itertools, sys

def nae_clause(clause, assign):
    vals=[assign[abs(l)-1] if l>0 else not assign[abs(l)-1] for l in clause]
    return not (all(vals) or not any(vals))

def is_good(clauses, num_vars):
    # returns True if NAE-satisfiable iff w (var 1) is False
    for assign in itertools.product([False,True], repeat=num_vars):
        sat = all(nae_clause(c, assign) for c in clauses)
        w = assign[0]
        if sat and w:
            return False
        if not sat and not w:
            # need at least one assignment with w false that satisfies
            # but we must ensure there exists a satisfying assignment when w false
            pass
    # check existence of satisfying assignment with w false
    exists=False
    for assign in itertools.product([False,True], repeat=num_vars):
        if assign[0]==False and all(nae_clause(c, assign) for c in clauses):
            exists=True
            break
    return exists

vars_range = [1,2,3]
# generate all possible clauses using vars 1..3 distinct
all_clauses=[]
for combo in itertools.combinations(vars_range,3):
    for signs in itertools.product([1,-1], repeat=3):
        clause=[s*v for s,v in zip(signs, combo)]
        all_clauses.append(clause)

for r in range(1,4):
    for combo in itertools.combinations(all_clauses, r):
        if is_good(combo, 3):
            print('found', r, combo)
            sys.exit()
print('none')
